using System.ComponentModel.DataAnnotations;

namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }

    [Required, StringLength(100)]
    public string Title { get; set; } = string.Empty;

    [Required]
    public string Category { get; set; } = string.Empty;

    public string Description { get; set; } = string.Empty;

    [Required, MinLength(1, ErrorMessage = "At least one ingredient is required.")]
    public string Ingredients { get; set; } = string.Empty;

    [Required, MinLength(1, ErrorMessage = "At least one step is required.")]
    public string Steps { get; set; } = string.Empty;

    public List<int> Ratings { get; set; } = new();

    public double AverageRating =>
        Ratings.Count > 0 ? Math.Round(Ratings.Average(), 1) : 0;

    public int RatingCount => Ratings.Count;
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes = new List<Recipe>
        {
            new()
            {
                Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
                Description = "A simple and delicious Neapolitan pizza with fresh mozzarella.",
                Ingredients = "Pizza dough\nSan Marzano tomatoes\nFresh mozzarella\nFresh basil\nOlive oil\nSalt",
                Steps = "Preheat oven to 475°F (245°C).\nStretch dough into a 12-inch round.\nSpread crushed tomatoes over dough.\nTear mozzarella and distribute evenly.\nBake for 10-12 minutes until crust is golden.\nTop with fresh basil and a drizzle of olive oil.",
                Ratings = new List<int> { 5, 4, 5, 5, 4 }
            },
            new()
            {
                Id = 2, Title = "Chicken Tikka Masala", Category = "Indian",
                Description = "Tender chicken pieces in a creamy, spiced tomato sauce.",
                Ingredients = "Chicken breast\nYogurt\nGaram masala\nTurmeric\nCumin\nCrushed tomatoes\nHeavy cream\nOnion\nGarlic\nGinger\nCilantro",
                Steps = "Marinate chicken in yogurt and spices for 1 hour.\nGrill or pan-sear chicken until charred.\nSauté onion, garlic, and ginger in a pan.\nAdd crushed tomatoes and spices; simmer 15 minutes.\nAdd cream and cooked chicken; simmer 10 minutes.\nGarnish with cilantro and serve with rice.",
                Ratings = new List<int> { 5, 5, 4, 5 }
            },
            new()
            {
                Id = 3, Title = "Beef Tacos", Category = "Mexican",
                Description = "Seasoned ground beef tacos with fresh toppings.",
                Ingredients = "Ground beef\nTaco seasoning\nCorn tortillas\nLettuce\nTomato\nCheddar cheese\nSour cream\nSalsa",
                Steps = "Brown ground beef in a skillet over medium-high heat.\nAdd taco seasoning and water; simmer 5 minutes.\nWarm tortillas in a dry pan.\nAssemble tacos with beef and desired toppings.\nServe immediately.",
                Ratings = new List<int> { 4, 4, 5, 3 }
            },
            new()
            {
                Id = 4, Title = "Pad Thai", Category = "Thai",
                Description = "Classic Thai stir-fried rice noodles with shrimp and peanuts.",
                Ingredients = "Rice noodles\nShrimp\nEggs\nBean sprouts\nGreen onions\nPeanuts\nLime\nFish sauce\nTamarind paste\nSugar\nGarlic",
                Steps = "Soak rice noodles in warm water for 30 minutes; drain.\nMix fish sauce, tamarind paste, and sugar for the sauce.\nStir-fry garlic and shrimp in a hot wok.\nPush to the side; scramble eggs in the wok.\nAdd noodles and sauce; toss until coated.\nTop with bean sprouts, peanuts, green onions, and lime.",
                Ratings = new List<int> { 5, 4, 4 }
            },
            new()
            {
                Id = 5, Title = "Caesar Salad", Category = "American",
                Description = "Crisp romaine with homemade Caesar dressing and croutons.",
                Ingredients = "Romaine lettuce\nParmesan cheese\nCroutons\nAnchovy fillets\nGarlic\nLemon juice\nDijon mustard\nOlive oil\nEgg yolk",
                Steps = "Blend anchovy, garlic, lemon juice, mustard, and egg yolk.\nSlowly drizzle in olive oil while blending to emulsify.\nTear romaine into bite-sized pieces.\nToss with dressing and shaved Parmesan.\nTop with croutons and serve.",
                Ratings = new List<int> { 4, 3, 4, 5 }
            },
            new()
            {
                Id = 6, Title = "Spaghetti Carbonara", Category = "Italian",
                Description = "Creamy Roman pasta made with eggs, cheese, and pancetta.",
                Ingredients = "Spaghetti\nPancetta\nEggs\nPecorino Romano\nBlack pepper\nSalt",
                Steps = "Cook spaghetti in salted boiling water until al dente.\nCrisp pancetta in a skillet; remove from heat.\nWhisk eggs with grated Pecorino and pepper.\nToss hot pasta with pancetta, then quickly stir in egg mixture.\nServe immediately with extra Pecorino and pepper.",
                Ratings = new List<int> { 5, 5, 5 }
            },
            new()
            {
                Id = 7, Title = "Guacamole", Category = "Mexican",
                Description = "Fresh and chunky avocado dip with lime and cilantro.",
                Ingredients = "Avocados\nLime juice\nCilantro\nRed onion\nJalapeño\nTomato\nSalt\nCumin",
                Steps = "Halve avocados and scoop into a bowl.\nMash to desired consistency.\nStir in diced onion, tomato, jalapeño, and cilantro.\nAdd lime juice, salt, and cumin to taste.\nServe with tortilla chips.",
                Ratings = new List<int> { 4, 5, 4, 4, 5 }
            },
            new()
            {
                Id = 8, Title = "Miso Soup", Category = "Japanese",
                Description = "A light and savory Japanese soup with tofu and seaweed.",
                Ingredients = "Dashi stock\nWhite miso paste\nSilken tofu\nWakame seaweed\nGreen onions",
                Steps = "Bring dashi stock to a gentle simmer.\nRehydrate wakame in warm water; drain.\nCube silken tofu.\nDissolve miso paste into the warm dashi (do not boil).\nAdd tofu and wakame.\nLadle into bowls and garnish with sliced green onions.",
                Ratings = new List<int> { 4, 4, 3 }
            }
        };
        _nextId = 9;
    }

    public IReadOnlyList<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().Order().ToList();
    }

    public IReadOnlyList<Recipe> GetByCategory(string category)
    {
        return _recipes.Where(r =>
            r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.Ratings.Add(stars);
        }
    }

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _nextId++;
        _recipes.Add(recipe);
    }
}

