@page "/"

<PageTitle>RecipeShare — Home</PageTitle>

<h1>Welcome to RecipeShare 🍳</h1>
<p class="lead">Discover and share your favorite recipes from around the world.</p>

<div class="row mt-4">
    @foreach (var category in categories)
    {
        <div class="col-md-4 mb-4">
            <div class="card h-100 shadow-sm">
                <div class="card-body text-center">
                    <h3 class="card-title">@GetEmoji(category) @category</h3>
                    <p class="card-text text-muted">
                        @recipes.Count(r => r.Category == category) recipe(s)
                    </p>
                    <a href="@($"categories/{category}")" class="btn btn-outline-primary">
                        Browse @category
                    </a>
                </div>
            </div>
        </div>
    }
</div>

<div class="mt-4 p-4 bg-light rounded">
    <h4>Ready to share your own recipe?</h4>
    <p>Join our community and contribute your favorite dishes!</p>
    <a href="submit" class="btn btn-success">Submit a Recipe</a>
</div>

@code {
    [Inject] private RecipeShare.Services.RecipeService RecipeService { get; set; } = default!;

    private IReadOnlyList<string> categories = Array.Empty<string>();
    private IReadOnlyList<RecipeShare.Models.Recipe> recipes = Array.Empty<RecipeShare.Models.Recipe>();

    protected override void OnInitialized()
    {
        categories = RecipeService.GetCategories();
        recipes = categories.SelectMany(c => RecipeService.GetByCategory(c)).ToList();
    }

    private static string GetEmoji(string category) => category switch
    {
        "American" => "🇺🇸",
        "Indian" => "🇮🇳",
        "Italian" => "🇮🇹",
        "Japanese" => "🇯🇵",
        "Mexican" => "🇲🇽",
        "Thai" => "🇹🇭",
        _ => "🍽️"
    };
}

