@page "/categories"
@page "/categories/{CategoryName}"

<PageTitle>@(CategoryName is not null ? $"{CategoryName} Recipes" : "Browse Recipes") — RecipeShare</PageTitle>

@if (CategoryName is null)
{
    <h1>Browse by Category</h1>
    <div class="list-group mt-3">
        @foreach (var cat in categories)
        {
            <a href="@($"categories/{cat}")" class="list-group-item list-group-item-action d-flex justify-content-between align-items-center">
                @cat
                <span class="badge bg-primary rounded-pill">@RecipeService.GetByCategory(cat).Count</span>
            </a>
        }
    </div>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="categories">All Categories</a></li>
            <li class="breadcrumb-item active" aria-current="page">@CategoryName</li>
        </ol>
    </nav>

    <h1>@CategoryName Recipes</h1>

    @if (recipes.Count == 0)
    {
        <div class="alert alert-info mt-3">No recipes found in this category.</div>
    }
    else
    {
        <div class="row mt-3">
            @foreach (var recipe in recipes)
            {
                <div class="col-md-6 mb-4">
                    <div class="card h-100 shadow-sm">
                        <div class="card-body">
                            <h5 class="card-title">@recipe.Title</h5>
                            <p class="card-text text-muted">@recipe.Description</p>
                            <div class="mb-2">
                                @for (int i = 1; i <= 5; i++)
                                {
                                    <span style="color: @(i <= Math.Round(recipe.AverageRating) ? "gold" : "#ccc");">★</span>
                                }
                                <small class="text-muted ms-1">@recipe.AverageRating / 5 (@recipe.RatingCount ratings)</small>
                            </div>
                            <a href="@($"recipe/{recipe.Id}")" class="btn btn-sm btn-outline-primary">View Recipe</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
}

@code {
    [Parameter] public string? CategoryName { get; set; }
    [Inject] private RecipeShare.Services.RecipeService RecipeService { get; set; } = default!;

    private IReadOnlyList<string> categories = Array.Empty<string>();
    private IReadOnlyList<RecipeShare.Models.Recipe> recipes = Array.Empty<RecipeShare.Models.Recipe>();

    protected override void OnParametersSet()
    {
        categories = RecipeService.GetCategories();
        recipes = CategoryName is not null
            ? RecipeService.GetByCategory(CategoryName)
            : Array.Empty<RecipeShare.Models.Recipe>();
    }
}

@page "/recipe/{Id:int}"

<PageTitle>@(recipe?.Title ?? "Recipe") — RecipeShare</PageTitle>

@if (recipe is null)
{
    <div class="alert alert-warning">Recipe not found.</div>
    <a href="categories" class="btn btn-outline-secondary">Back to Categories</a>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="categories">All Categories</a></li>
            <li class="breadcrumb-item"><a href="@($"categories/{recipe.Category}")">@recipe.Category</a></li>
            <li class="breadcrumb-item active" aria-current="page">@recipe.Title</li>
        </ol>
    </nav>

    <h1>@recipe.Title</h1>
    <p class="lead text-muted">@recipe.Description</p>
    <span class="badge bg-secondary mb-3">@recipe.Category</span>

    <div class="row mt-3">
        <div class="col-md-4">
            <div class="card mb-3">
                <div class="card-header"><strong>Ingredients</strong></div>
                <ul class="list-group list-group-flush">
                    @foreach (var ingredient in recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                    {
                        <li class="list-group-item">@ingredient</li>
                    }
                </ul>
            </div>
        </div>

        <div class="col-md-8">
            <div class="card mb-3">
                <div class="card-header"><strong>Steps</strong></div>
                <div class="card-body">
                    <ol>
                        @foreach (var step in recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                        {
                            <li class="mb-2">@step</li>
                        }
                    </ol>
                </div>
            </div>
        </div>
    </div>

    <div class="card mt-3">
        <div class="card-body">
            <h5>Rate this recipe</h5>
            <StarRating RecipeId="recipe.Id" />
        </div>
    </div>
}

@code {
    [Parameter] public int Id { get; set; }
    [Inject] private RecipeShare.Services.RecipeService RecipeService { get; set; } = default!;

    private RecipeShare.Models.Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetById(Id);
    }
}

@rendermode InteractiveServer

<div class="d-inline-block">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span
            @onclick="() => SubmitRating(star)"
            style="cursor: pointer; font-size: 1.5rem; color: @(star <= (hoverRating ?? currentRating) ? "gold" : "#ccc");"
            @onmouseover="() => hoverRating = star"
            @onmouseout="() => hoverRating = null"
            role="button"
            aria-label="@($"Rate {star} star{(star > 1 ? "s" : "")}")">
            ★
        </span>
    }

    @if (submitted)
    {
        <span class="text-success ms-2">✓ Rated @currentRating star@(currentRating != 1 ? "s" : "")!</span>
    }

    <div class="text-muted small mt-1">
        @recipe?.AverageRating / 5 — @recipe?.RatingCount rating(s)
    </div>
</div>

@code {
    [Parameter, EditorRequired] public int RecipeId { get; set; }
    [Inject] private RecipeShare.Services.RecipeService RecipeService { get; set; } = default!;

    private RecipeShare.Models.Recipe? recipe;
    private int currentRating;
    private int? hoverRating;
    private bool submitted;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetById(RecipeId);
    }

    private void SubmitRating(int stars)
    {
        currentRating = stars;
        RecipeService.AddRating(RecipeId, stars);
        recipe = RecipeService.GetById(RecipeId);
        submitted = true;
    }
}

@page "/submit"
@rendermode InteractiveServer

<PageTitle>Submit a Recipe — RecipeShare</PageTitle>

<h1>Submit a Recipe</h1>
<p class="text-muted">Share your favorite recipe with the community.</p>

@if (successMessage is not null)
{
    <div class="alert alert-success">
        @successMessage
        <a href="@($"recipe/{submittedId}")" class="alert-link">View your recipe →</a>
    </div>
}

<EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
    <DataAnnotationsValidator />
    <ValidationSummary class="text-danger" />

    <div class="mb-3">
        <label for="title" class="form-label">Recipe Title</label>
        <InputText id="title" @bind-Value="model.Title" class="form-control" placeholder="e.g. Grandma's Apple Pie" />
        <ValidationMessage For="() => model.Title" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="category" class="form-label">Category</label>
        <InputSelect id="category" @bind-Value="model.Category" class="form-select">
            <option value="">— Select a category —</option>
            @foreach (var cat in categories)
            {
                <option value="@cat">@cat</option>
            }
            <option value="Other">Other</option>
        </InputSelect>
        <ValidationMessage For="() => model.Category" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="description" class="form-label">Short Description</label>
        <InputText id="description" @bind-Value="model.Description" class="form-control" placeholder="A brief summary of the dish" />
    </div>

    <div class="mb-3">
        <label for="ingredients" class="form-label">Ingredients (one per line)</label>
        <InputTextArea id="ingredients" @bind-Value="model.Ingredients" class="form-control" rows="6"
            placeholder="2 cups flour&#10;1 cup sugar&#10;3 eggs" />
        <ValidationMessage For="() => model.Ingredients" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="steps" class="form-label">Steps (one per line)</label>
        <InputTextArea id="steps" @bind-Value="model.Steps" class="form-control" rows="6"
            placeholder="Preheat oven to 350°F.&#10;Mix dry ingredients.&#10;Combine wet ingredients." />
        <ValidationMessage For="() => model.Steps" class="text-danger" />
    </div>

    <button type="submit" class="btn btn-primary">Submit Recipe</button>
</EditForm>

@code {
    [Inject] private RecipeShare.Services.RecipeService RecipeService { get; set; } = default!;

    private RecipeShare.Models.Recipe model = new();
    private IReadOnlyList<string> categories = Array.Empty<string>();
    private string? successMessage;
    private int submittedId;

    protected override void OnInitialized()
    {
        categories = RecipeService.GetCategories();
    }

    private void HandleSubmit()
    {
        RecipeService.AddRecipe(model);
        submittedId = model.Id;
        successMessage = $""{model.Title}" was submitted successfully!";
        model = new();
    }
}

